-- Invoice & Payment Service: initial schema.
--
-- Conventions:
--   * Primary keys are UUIDv7 generated by the application (time-ordered, so they
--     index well and double as the pagination cursor).
--   * Money is BIGINT minor units (USD cents). No floating point anywhere.
--   * Status columns are TEXT + CHECK rather than Postgres ENUMs: same integrity,
--     and adding a state later is a plain constraint swap instead of ALTER TYPE.
--   * Every tenant-owned row carries business_id.

CREATE TABLE businesses (
    id          UUID PRIMARY KEY,
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Keys look like sk_<prefix:8>_<secret:32>. We store the prefix in plaintext
-- (lookup) and SHA-256 of the full key; the plaintext key is shown once.
CREATE TABLE api_keys (
    id           UUID PRIMARY KEY,
    business_id  UUID NOT NULL REFERENCES businesses (id),
    prefix       TEXT NOT NULL UNIQUE,
    key_hash     BYTEA NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at   TIMESTAMPTZ
);
CREATE INDEX api_keys_business_idx ON api_keys (business_id);

-- Email is deliberately not unique (Stripe allows duplicate customers).
CREATE TABLE customers (
    id           UUID PRIMARY KEY,
    business_id  UUID NOT NULL REFERENCES businesses (id),
    name         TEXT NOT NULL,
    email        TEXT NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- Target of the tenant-safe composite FK from invoices; also serves
    -- "list customers for business, newest first".
    UNIQUE (business_id, id)
);

CREATE TABLE invoices (
    id                  UUID PRIMARY KEY,
    business_id         UUID NOT NULL REFERENCES businesses (id),
    customer_id         UUID NOT NULL,
    status              TEXT NOT NULL
        CHECK (status IN ('draft', 'open', 'processing', 'paid', 'void', 'uncollectible')),
    -- Where a failed payment returns the invoice to. Set in the same UPDATE that
    -- moves the invoice to 'processing' (SET-list right-hand sides see the old row).
    pre_payment_status  TEXT CHECK (pre_payment_status IN ('open', 'uncollectible')),
    total_cents         BIGINT NOT NULL CHECK (total_cents > 0),
    due_date            DATE NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    paid_at             TIMESTAMPTZ,
    -- An invoice can only reference a customer of the same business.
    FOREIGN KEY (business_id, customer_id) REFERENCES customers (business_id, id),
    CHECK ((status = 'processing') = (pre_payment_status IS NOT NULL)),
    CHECK ((status = 'paid') = (paid_at IS NOT NULL))
);
CREATE INDEX invoices_business_idx ON invoices (business_id, id);
CREATE INDEX invoices_business_status_idx ON invoices (business_id, status, id);

CREATE TABLE invoice_line_items (
    id                 UUID PRIMARY KEY,
    invoice_id         UUID NOT NULL REFERENCES invoices (id),
    position           INT NOT NULL,
    description        TEXT NOT NULL CHECK (length(description) BETWEEN 1 AND 500),
    quantity           INT NOT NULL CHECK (quantity BETWEEN 1 AND 1000000),
    unit_amount_cents  BIGINT NOT NULL CHECK (unit_amount_cents >= 0),
    amount_cents       BIGINT NOT NULL CHECK (amount_cents = quantity * unit_amount_cents),
    UNIQUE (invoice_id, position)
);

CREATE TABLE payment_attempts (
    id            UUID PRIMARY KEY,   -- also the idempotency key sent to the PSP
    invoice_id    UUID NOT NULL REFERENCES invoices (id),
    business_id   UUID NOT NULL REFERENCES businesses (id),
    status        TEXT NOT NULL CHECK (status IN ('pending', 'unknown', 'succeeded', 'failed')),
    amount_cents  BIGINT NOT NULL CHECK (amount_cents > 0),
    card_token    TEXT NOT NULL,      -- PSP token, never a card number
    psp_ref       TEXT,
    failure_code  TEXT,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at   TIMESTAMPTZ
);
CREATE INDEX payment_attempts_invoice_idx ON payment_attempts (invoice_id, id);
-- Schema-level backstops for "one payment in flight" and "never paid twice".
CREATE UNIQUE INDEX payment_attempts_one_in_flight
    ON payment_attempts (invoice_id) WHERE status IN ('pending', 'unknown');
CREATE UNIQUE INDEX payment_attempts_one_success
    ON payment_attempts (invoice_id) WHERE status = 'succeeded';
-- Reconciler scan.
CREATE INDEX payment_attempts_unresolved_idx
    ON payment_attempts (created_at) WHERE status IN ('pending', 'unknown');

CREATE TABLE idempotency_keys (
    business_id         UUID NOT NULL REFERENCES businesses (id),
    key                 TEXT NOT NULL,
    request_hash        BYTEA NOT NULL,          -- sha256(method, path, canonical body)
    status              TEXT NOT NULL CHECK (status IN ('in_progress', 'completed')),
    response_code       SMALLINT,
    response_body       BYTEA,                   -- exact bytes sent, for byte-identical replay
    payment_attempt_id  UUID REFERENCES payment_attempts (id),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at          TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (business_id, key),
    CHECK ((status = 'completed') = (response_code IS NOT NULL AND response_body IS NOT NULL))
);
CREATE UNIQUE INDEX idempotency_keys_attempt_idx
    ON idempotency_keys (payment_attempt_id) WHERE payment_attempt_id IS NOT NULL;

CREATE TABLE webhook_endpoints (
    id           UUID PRIMARY KEY,
    business_id  UUID NOT NULL REFERENCES businesses (id),
    url          TEXT NOT NULL,
    secret       TEXT NOT NULL,   -- plaintext: HMAC signing needs it (encryption at rest is a prod gap)
    active       BOOLEAN NOT NULL DEFAULT true,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX webhook_endpoints_business_idx ON webhook_endpoints (business_id) WHERE active;

-- Transactional outbox: written in the same transaction as the state change.
CREATE TABLE webhook_events (
    id           UUID PRIMARY KEY,
    business_id  UUID NOT NULL REFERENCES businesses (id),
    type         TEXT NOT NULL,
    payload      JSONB NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX webhook_events_business_idx ON webhook_events (business_id, id);

CREATE TABLE webhook_deliveries (
    id                UUID PRIMARY KEY,
    event_id          UUID NOT NULL REFERENCES webhook_events (id),
    endpoint_id       UUID NOT NULL REFERENCES webhook_endpoints (id),
    status            TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'delivered', 'dead')),
    attempts          INT NOT NULL DEFAULT 0,      -- completed tries (lease expiry does not count)
    next_attempt_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_status_code  SMALLINT,
    last_error        TEXT,
    delivered_at      TIMESTAMPTZ,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (event_id, endpoint_id)
);
CREATE INDEX webhook_deliveries_due_idx ON webhook_deliveries (next_attempt_at) WHERE status = 'pending';
